"""ferry freight: rate lookup."""
import csv
import json
import configparser

DEFAULT_PATH = "data/rates_2025.json"


def load_rates(path=DEFAULT_PATH):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def quote(zone, qty, rates, flags=()):
    if zone not in rates["zones"]:
        raise KeyError(zone)
    if qty < 1:
        raise ValueError("qty must be at least 1")
